            {'drug': 'فلوتیکازون (Fluticasone Propionate / Flovent HFA, Flonase)', 'class': 'کورتیکواستروئید استنشاقی پرقدرت با جذب سیستمیک بسیار ناچیز (ICS)', 'mechanism': 'اتصال به گیرنده\u200cهای گلوکوکورتیکوئیدی سیتوپلاسمی؛ مهار فاکتور رونویسی NF-kB و مهار ساخت سیتوکین\u200cهای التهابی (IL-4, IL-5)، مهار مهاجرت ائوزینوفیل\u200cها و افزایش بیان گیرنده\u200cهای بتا-۲', 'indication': 'خط اول درمان ضدالتهابی نگهدارنده در آسم مداوم (خفیف تا شدید)، درمان رینیت آلرژیک (اسپری بینی)', 'kinetics': 'برگرفته از جزوه قلب ص ۲۲، ۲۳، ۲۴؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'کاندیدیازیس دهانی-حلقی (برفک دهان ناشی از سرکوب موضعی ایمنی)، دیسفونی و گرفتگی صدا ناشی از میوپاتی تارهای صوتی، سرفه ناشی از محرک اسپری، در مصرف دوز بالا اختلال رشد خفیف در کودکان', 'nursing_alerts': 'بیمار باید بلافاصله پس از هر بار استنشاق، دهان و حلق خود را با آب کاملاً قرقره کرده و آب را بیرون بریزد تا از بروز برفک و خشونت صدا جلوگیری شود؛ استفاده مداوم از محفظه دمی\u200cیار (Spacer).', 'antidote': 'نیستاتین موضعی دهانی برای درمان برفک'},
            {'drug': 'بودزوناید (Budesonide / Pulmicort Flexhaler, Pulmicort Respules)', 'class': 'کورتیکواستروئید استنشاقی با کلیرانس کبدی سریع (استریفیه شدن درون\u200cسلولی)', 'mechanism': 'ایجاد پیوند استری با اسیدهای چرب درون\u200cسلولی در بافت ریه؛ ایجاد مخزن موضعی دارو در راه\u200cهای هوایی و مهار التهاب مداوم با حداقل ورود به خون سیستمیک', 'indication': 'درمان نگهدارنده آسم مزمن در بزرگسالان و اطفال، درمان کروپ (خروسک حاد تنفسی) در اطفال با سوسپانسیون نبولایزر (Respules)', 'kinetics': 'برگرفته از جزوه قلب ص ۲۲، ۲۳، ۲۴؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'عفونت قارچی کاندیدیاز دهان، سرفه، فارنژیت، خشونت صدا', 'nursing_alerts': 'تنها کورتیکواستروئید استنشاقی است که در دوران بارداری در رده B قرار دارد و ایمن\u200cترین ICS در بارداری محسوب می\u200cشود؛ فرم نبولایزر برای شیرخواران و کودکان بسیار مناسب است.', 'antidote': 'شستشوی دهان، نیستاتین موضعی'},
            {'drug': 'بکلومتازون و فلونیزولید (Beclomethasone & Flunisolide / Qvar & Aerobid)', 'class': 'کورتیکواستروئیدهای استنشاقی با اندازه ذرات فوق\u200cالعاده ریز (Extra-fine particles)', 'mechanism': 'بکلومتازون دی\u200cپروپیونات یک پیش\u200cدارو است که در ریه توسط استرازها به منوپروپیونات فعال تبدیل می\u200cشود؛ ذرات ریز آن تا عمق مجاری هوایی کوچک و آلوئول\u200cها نفوذ می\u200cکنند', 'indication': 'درمان نگهدارنده آسم پایدار، کنترل التهاب مجاری هوایی محیطی', 'kinetics': 'برگرفته از جزوه قلب ص ۲۲، ۲۳، ۲۴؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'برفک دهانی، خشکی گلو، سرفه، تحریک مجاری فوقانی تنفسی', 'nursing_alerts': 'به دلیل اندازه ریز ذرات معلق (با تکنولوژی محلول HFA)، رسوب دهانی کمتری نسبت به پودرهای سنتی دارد اما شستشوی دهان کماکان الزامی است.', 'antidote': 'درمان علامتی و ضدقارچ موضعی'},
            {'drug': 'سیکلسوناید و مومتازون (Ciclesonide & Mometasone / Alvesco & Asmanex Twisthaler)', 'class': 'کورتیکواستروئیدهای استنشاقی نسل جدید با تمایل بسیار بالا به گیرنده', 'mechanism': 'سیکلسوناید در اوروفارنکس کاملاً غیرفعال است و فقط پس از استنشاق به راه\u200cهای هوایی تحتانی توسط استرازهای ریوی فعال می\u200cشود (کمترین میزان برفک دهانی)؛ مومتازون قوی\u200cترین تمایل اتصالی به گیرنده گلوکوکورتیکوئید را دارد', 'indication': 'کنترل روزانه آسم پایدار، کاهش نیاز به کورتون\u200cهای خوراکی در آسم وابسته به استروئید', 'kinetics': 'برگرفته از جزوه قلب ص ۲۲، ۲۳، ۲۴؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'سردرد، فارنژیت، سینوزیت، عفونت\u200cهای مجاری فوقانی تنفس', 'nursing_alerts': 'سیکلسوناید به دلیل فعال\u200cسازی منحصراً در ریه، شیوع کاندیدیازیس دهانی را به زیر ۱٪ می\u200cرساند؛ مصرف یک بار در روز در شب.', 'antidote': 'قطع مصرف یا کاهش دوز'},
            {'drug': 'فرآورده\u200cهای استنشاقی ترکیبی (Fluticasone/Salmeterol, Budesonide/Formoterol & Mometasone/Formoterol / Advair Diskus, Symbicort, Dulera)', 'class': 'اسپری\u200cهای ترکیبی ثابت کورتیکواستروئید استنشاقی + آگونیست طولانی\u200cاثر بتا-۲ (ICS/LABA)', 'mechanism': 'هم\u200cافزایی مولکولی فوق\u200cالعاده: کورتیکواستروئیدها بیان گیرنده\u200cهای بتا-۲ را افزایش داده و از حساسیت\u200cزدایی آنها جلوگیری می\u200cکنند و آگونیست\u200cهای بتا-۲ انتقال گیرنده گلوکوکورتیکوئیدی به هسته را تسهیل می\u200cسازند', 'indication': 'کنترل طولانی\u200cمدت آسم متوسط تا شدید پایدار کنترل\u200cنشده با ICS به تنهایی، درمان نگهدارنده COPD شدید', 'kinetics': 'برگرفته از جزوه قلب ص ۲۲، ۲۳، ۲۴؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'خشونت صدا، برفک دهان، لرزش دست\u200cها، تپش قلب، خطرات مربوط به LABA در صورت مصرف نامناسب', 'nursing_alerts': 'سیمبیکورت (بودزوناید/فورموترول) بر اساس استراتژی SMART می\u200cتواند هم به عنوان داروی نگهدارنده روزانه و هم داروی تسکین\u200cدهنده سریع در زمان حمله (به دلیل شروع اثر سریع فورموترول) استفاده شود؛ شستشوی دهان پس از هر بار مصرف الزامی است.', 'antidote': 'درمان علامتی و شستشوی دهان'},
            {'drug': 'مونته\u200cلوکاست و زافیرلوکاست (Montelukast & Zafirlukast / Singulair & Accolate)', 'class': 'آنتاگونیست\u200cهای انتخابی گیرنده لوکوترین D4 (LTRA)', 'mechanism': 'مسدود کردن گیرنده\u200cهای CysLT1 در عضلات صاف مجاری تنفسی و سلول\u200cهای التهابی؛ مهار برونکواسپاسم، ادم مخاطی و ترشح موکوس ناشی از LTC4, LTD4, LTE4', 'indication': 'درمان کمکی آسم مداوم، پیشگیری از برونکواسپاسم ناشی از فعالیت ورزشی (EIB)، درمان رینیت آلرژیک، داروی انتخابی در آسم حساس به آسپرین (Aspirin-exacerbated respiratory disease)', 'kinetics': 'برگرفته از جزوه قلب ص ۲۲، ۲۳؛ جزوه مامایی ص ۱۰؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'تغییرات عصبی-روانی جدی (Nightmares، کابوس\u200cهای شبانه، افسردگی، بی\u200cقراری، افکار خودکشی / Black Box Warning)، سردرد، درد شکمی، سندرم چرگ اشتراوس (ائوزینوفیلی و واسکولیت)، سمیت کبدی با زافیرلوکاست', 'nursing_alerts': 'قرص مونته\u200cلوکاست باید عصرها مصرف شود؛ به والدین کودکان در خصوص تغییرات رفتاری، پرخاشگری و کابوس\u200cهای شبانه هشدار جدی داده شود و در صورت مشاهده دارو فوراً قطع گردد؛ زافیرلوکاست باید با معده خالی (۱ ساعت قبل یا ۲ ساعت بعد غذا) مصرف شود.', 'antidote': 'قطع فوری دارو، پایش روانی'},
            {'drug': 'زیلوتون (Zileuton / Zyflo)', 'class': 'مهارکننده مستقیم آنزیم ۵-لیپواکسیژناز (5-LOX Inhibitor)', 'mechanism': 'مهار مستقیم آنزیم ۵-لیپواکسیژناز و مسدود کردن سنتز تمام لوکوترین\u200cها (شامل LTB4 و سیستئینیل لوکوترین\u200cها) از اسید آراشیدونیک', 'indication': 'درمان پیشگیرانه و مزمن آسم در بزرگسالان و نوجوانان بالای ۱۲ سال', 'kinetics': 'برگرفته از جزوه قلب ص ۲۲؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'سمیت شدید کبدی و افزایش ترانس\u200cآمینازها (در ۳ تا ۵ درصد بیماران)، تداخلات شدید دارویی با تئوفیلین و وارفارین (افزایش غلظت خونی آنها)', 'nursing_alerts': 'بررسی منظم آنزیم\u200cهای کبدی ALT در ابتدای درمان و ماهیانه برای ۶ ماه اول؛ بیمار باید از نظر علائم هپاتیت (یرقان، خستگی، ادرار تیره) پایش شود.', 'antidote': 'قطع دارو'},
