            {'drug': 'فسفنی\u200cتوئین (Fosphenytoin / Cerebyx)', 'class': 'پیش\u200cداروی استر فسفات محلول در آب فنی\u200cتوئین جهت تزریق وریدی/عضلانی', 'mechanism': 'پس از تزریق به سرعت توسط فسفاتازهای خون و کبد با نیمه\u200cعمر ۱۵ دقیقه به فنی\u200cتوئین فعال تبدیل می\u200cشود؛ فاقد حلال پروپیلن گلیکول', 'indication': 'درمان اورژانس استاتوس اپی\u200cلپتیکوس و جایگزین فنی\u200cتوئین وریدی و عضلانی در بیمارستان', 'kinetics': 'برگرفته از جزوه قلب ص ۴۳، ۴۵؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'خارش گذرا در ناحیه پرینه، سرگیجه، تاری دید، نیستاگموس، افت فشارخون گذرا', 'nursing_alerts': 'می\u200cتواند ۳ برابر سریع\u200cتر از فنی\u200cتوئین (تا ۱۵۰ میلی\u200cگرم در دقیقه) تزریق شود و عوارض سوزش رگ و افت فشارخون بسیار کمتری دارد؛ امکان تزریق داخل عضلانی (IM) را بر خلاف فنی\u200cتوئین فراهم می\u200cکند.', 'antidote': 'درمان حمایتی قلبی-عروقی'},
            {'drug': 'کاربامازپین و اکس\u200cکاربازپین (Carbamazepine & Oxcarbazepine / Tegretol & Trileptal)', 'class': 'ضد تشنج\u200cهای ایمینوستیلبنی مسدودکننده کانال سدیم', 'mechanism': 'بلوک کانال\u200cهای سدیم وابسته به ولتاژ در نورون\u200cهای صرعی؛ پدیده خودالقایی آنزیمی (Auto-induction: کاربامازپین تولید آنزیم CYP3A4 را القا کرده و سرعت متابولیسم خودش را افزایش می\u200cدهد به طوری که نیمه\u200cعمر دارو پس از چند هفته کاهش می\u200cیابد)', 'indication': 'خط اول درمان صرع تشنجات فوکال (ساده و پیچیده) و تونیک-کلونیک جنرالیزه، داروی انتخابی و اختصاصی در نورالژی عصب سه قلو (Trigeminal Neuralgia)، تثبیت\u200cکننده خلق در اختلال دوقطبی مقاوم', 'kinetics': 'برگرفته از جزوه قلب ص ۴۲، ۴۳، ۴۴، ۴۵؛ جزوه مامایی ص ۴، ۱۰، ۱۷؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'سندرم استیونز-جانسون (SJS) و نکروز اپیدرمال توکسیک (TEN) به ویژه در افراد با الل ژنتیکی HLA-B*1502؛ اگرانولوسیتوز کشنده و آنمی آپلاستیک (Black Box Warning)، هایپوناترمی ناشی از اثر شبه\u200cSIADH، آتاکسی، دوبینی، تراتوژن (نقص لوله عصبی اسپینا بیفیدا / رده D)', 'nursing_alerts': 'غربالگری ژنتیکی الل HLA-B*1502 قبل از شروع دارو در نژادهای آسیایی؛ انجام آزمایش CBC منظم و شمارش گلبول\u200cهای سفید؛ پایش سدیم خون؛ اکس\u200cکاربازپین پیش\u200cدارویی با عوارض خونی و القای آنزیمی کمتر است اما هایپوناترمی بیشتری دارد.', 'antidote': 'قطع دارو، ذغال فعال مکرر و هموپرفیوژن در مسمومیت حاد'},
            {'drug': 'اسید والپروئیک / سدیم والپروات (Valproic Acid / Sodium Valproate / Depakene, Depakote)', 'class': 'داروی ضد صرع وسیع\u200cالطیف چندمکانیسمی (مشتق اسید چرب)', 'mechanism': 'بلوک کانال\u200cهای سدیم + بلوک کانال\u200cهای کلسیمی نوع T در تالاموس + مهار آنزیم گابا-ترانس\u200cآمیناز (GABA-T) و مهار بازجذب گابا و تحریک سنتز آن؛ مهار تمام انواع تشنج\u200cها', 'indication': 'خط اول درمان صرع\u200cهای مخلوط و میوکلونیک، تشنج\u200cهای تونیک-کلونیک، تشنج ابسانس (همراه یا بعد از اتوسوکسیماید)، فاز مانیا در دوقطبی، پیشگیری از میگرن', 'kinetics': 'برگرفته از جزوه قلب ص ۴۲، ۴۳، ۴۴، ۴۵، ۴۶؛ جزوه مامایی ص ۴، ۱۰، ۱۷؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'سمیت شدید و کشنده کبدی (Fatal Hepatotoxicity در کودکان زیر ۲ سال تحت پلی\u200cتراپی / Black Box Warning)، پانکراتیت حاد هموراژیک مرگبار، سندرم تراتوژنیک والپروات (بالاترین خطر نقص لوله عصبی Spina bifida حدود ۱ تا ۲ درصد و کاهش ضریب هوشی کودک)، افزایش آمونیاک خون بدون آسیب کبدی، ریزش مو و افزایش وزن قابل توجه، ترومبوسیتوپنی', 'nursing_alerts': 'منع مصرف مطلق در دوران بارداری مگر در غیاب هرگونه داروی دیگر؛ منع مصرف در کودکان زیر ۲ سال بدون نظارت فوق تخصصی؛ کنترل منظم تست\u200cهای عملکرد کبد (LFT) و پلاکت\u200cها؛ در صورت تهوع و درد شکم حاد فوراً آمیلاز و لیپاز جهت رد پانکراتیت چک شود.', 'antidote': 'ال-کارنیتین وریدی (L-Carnitine) پادزهر اختصاصی سمیت کبدی و هایپرآمونمی ناشی از والپروات است'},
            {'drug': 'اتوسوکسیماید و تری\u200cمتادیون (Ethosuximide & Trimethadione / Zarontin & Tridione)', 'class': 'مسدودکننده\u200cهای اختصاصی کانال کلسیم نوع T در تالاموس (ضد ابسانس)', 'mechanism': 'بلوک اختصاصی جریان کلسیمی گذرا و با ولتاژ پایین نوع T (T-type Ca2+ currents) در نورون\u200cهای رله تالاموس؛ سرکوب ریتم تخلیه امواج ۳ هرتز اسپایک و موج (3-Hz spike-and-wave)', 'indication': 'خط اول و داروی استاندارد طلایی درمان صرع کوچک یا تشنج ابسانس (Absence Seizures / Petit Mal) در کودکان', 'kinetics': 'برگرفته از جزوه قلب ص ۴۲، ۴۳، ۴۴، ۴۶؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'تحریک گوارشی، تهوع، بی\u200cاشتهایی و درد شکم (بسیار شایع)، خواب\u200cآلودگی، سردرد، سرگیجه، اگرانولوسیتوز نادر، سندرم استیونز جانسون', 'nursing_alerts': 'تنها داروی انتخابی در ابسانس خالص کودک بدون تشنج تونیک-کلونیک؛ در تشنج بزرگ بی\u200cاثر است؛ مصرف همراه با غذا یا شیر جهت کاهش تهوع.', 'antidote': 'قطع دارو و اقدامات حمایتی'},
            {'drug': 'لاموتریژین (Lamotrigine / Lamictal)', 'class': 'ضد صرع وسیع\u200cالطیف مهارکننده رهایش گلوتامات و کانال سدیم', 'mechanism': 'بلوک کانال\u200cهای سدیم وابسته به ولتاژ و مهار رهایش اسیدهای آمینه تحریکی گلوتامات و آسپارتات از پایانه\u200cهای عصبی', 'indication': 'تشنجات فوکال و جنرالیزه تونیک-کلونیک، تشنج ابسانس، سندرم لنوکس-گستو، درمان نگهدارنده فاز افسردگی در اختلال دوقطبی', 'kinetics': 'برگرفته از جزوه قلب ص ۴۲، ۴۳، ۴۴، ۴۵؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'راش\u200cهای پوستی بسیار خطرناک و کشنده سندرم استیونز-جانسون (SJS) و TEN (Black Box Warning)، گیجی، دوبینی، آتاکسی', 'nursing_alerts': 'دوز دارو باید بسیار کند و تدریجی طی چندین هفته افزایش یابد (Start low, go slow) تا از ایجاد راش\u200cهای جلدی کشنده پیشگیری شود؛ والپروات متابولیسم لاموتریژین را مهار کرده و غلظت آن را دو برابر می\u200cکند (دوز باید نصف شود).', 'antidote': 'قطع فوری دارو در صورت مشاهده هرگونه ضایعه پوستی یا تاول دهانی'},
            {'drug': 'توپیرامات (Topiramate / Topamax)', 'class': 'ضد صرع چندمکانیسمی و مهارکننده کربنیک آنهیدراز', 'mechanism': 'بلوک کانال\u200cهای سدیم + تقویت اثر گابا روی گیرنده GABAA + مهار گیرنده\u200cهای تحریکی گلوتامات کینات/AMPA + مهار ضعیف ایزوآنزیم\u200cهای کربنیک آنهیدراز (CA-II و CA-IV)', 'indication': 'تشنجات فوکال و تونیک-کلونیک جنرالیزه، سندرم لنوکس-گستو، پیشگیری از حملات میگرن مزمن، درمان چاقی و پرخوری عصبی', 'kinetics': 'برگرفته از جزوه قلب ص ۴۲، ۴۳، ۴۴؛ جزوه مامایی ص ۱۰؛ شاخص درمانی، زیست\u200cدست\u200cیابی و مسیر متابولیسم/دفع اختصاصی طبق کوریکولوم دکتر بهزاد فروتن.', 'toxicity': 'اختلال در توجه و تمرکز و کندی تفکر و تکلم (نام مستعار Dopamax)، سنگ\u200cهای کلیوی کلسیمی به دلیل مهار کربنیک آنهیدراز، اسیدوز متابولیک هیپوکلرمیک، کاهش تعریق و هایپرترمی (Oligohidrosis به ویژه در کودکان)، گلوکوم زاویه بسته حاد، کاهش وزن', 'nursing_alerts': 'توصیه به مصرف روزانه حداقل ۲ تا ۳ لیتر آب جهت پیشگیری از تشکیل سنگ کلیه؛ پایش کودکان در هوای گرم به دلیل نقص تعریق و ریسک گرمازدگی؛ اندازه\u200cگیری دوره\u200cای بی\u200cکربنات خون.', 'antidote': 'قطع دارو، هیدراتاسیون و بی\u200cکربنات سدیم در اسیدوز'},
